8	import org.springframework.samples.petclinic.model.Region;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "bulkSignupWarning", ignore = true)
30	    @Mapping(target = "identityKey", ignore = true)
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * Derives the owner's {@code contactPreference} from the owner's own fields:
35	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
36	     *
37	     * @param owner the owner being mapped
38	     * @return the derived contact preference
39	     */
40	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
41	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
42	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
43	    }
44	
45	    /**
46	     * Derives the owner's {@code locality} by preferring the {@code postcode}: it first looks up the
47	     * region by {@link Region#forPostcode(String) postcode range} (NSW 2000-2099, VIC 3000-3099,
48	     * QLD 4000-4099), and only falls back to the shared {@link Region#forCity(String) city-to-region}
49	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}) when the
50	     * postcode is absent or in no known range. Returns the canonical region code, or {@code UNKNOWN}
51	     * when neither the postcode nor the city resolves to a known region.
52	     *
53	     * @param owner the owner being mapped
54	     * @return the derived locality
55	     */
56	    default String locality(Owner owner) {
57	        return Region.forPostcode(owner.getPostcode())
58	            .or(() -> Region.forCity(owner.getCity()))
59	            .map(Region::name)
60	            .orElse("UNKNOWN");
61	    }
62	
63	    /**
64	     * Derives the owner's numeric {@code membershipLevel} from the owner's own fields. Starts at
65	     * {@code 1}, adds {@code 1} when an email is present, adds {@code 1} when the owner's
66	     * {@code namesakeCount} is {@code 0}, and is capped at {@code 3} (level {@code 4} is reserved
67	     * for tenure).
68	     *
69	     * @param owner the owner being mapped
70	     * @return the derived membership level, between {@code 1} and {@code 3}
71	     */
72	    default Integer membershipLevel(Owner owner) {
73	        int level = 1;
74	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
75	        if (hasEmail) {
76	            level++;
77	        }
78	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
79	        if (uniqueName) {
80	            level++;
81	        }
82	        return Math.min(level, 3);
83	    }
84	
85	    /**
86	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
87	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
88	     * {@code 'MEL-SMI-0007-M26'}). Returns {@code null} when either the customer code or the
89	     * registration date is absent.
90	     *
91	     * @param owner the owner being mapped
92	     * @return the formatted membership number, or {@code null} when it cannot be derived
93	     */
94	    default String membershipNumber(Owner owner) {
95	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
96	            return null;
97	        }
98	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
99	    }
100	
101	    /**
102	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
103	     * contained in the {@code customerCode} (non-digit characters, such as the {@code '<LAST3>-'}
104	     * prefix and the separator, are ignored). Returns {@code null} when the customer code is absent.
105	     *
106	     * @param owner the owner being mapped
107	     * @return the Luhn check digit, or {@code null} when no customer code is present
108	     */
109	    default Integer checkDigit(Owner owner) {
110	        String code = owner.getCustomerCode();
111	        if (code == null) {
112	            return null;
113	        }
114	        int sum = 0;
115	        boolean dbl = true;
116	        for (int i = code.length() - 1; i >= 0; i--) {
117	            char c = code.charAt(i);
118	            if (c < '0' || c > '9') {
119	                continue;
120	            }
121	            int d = c - '0';
122	            if (dbl) {
123	                d *= 2;
124	                if (d > 9) {
125	                    d -= 9;
126	                }
127	            }
128	            sum += d;
129	            dbl = !dbl;
130	        }
131	        return (10 - (sum % 10)) % 10;
132	    }
133	
134	    Owner toOwner(OwnerDto ownerDto);
135	
136	    @Mapping(target = "id", ignore = true)
137	    @Mapping(target = "pets", ignore = true)
138	    Owner toOwner(OwnerFieldsDto ownerDto);
139	
140	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
141	
142	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
143	
144	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
145	        OwnerPageDto ownerPageDto = new OwnerPageDto();
146	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
147	        ownerPageDto.setPage(ownerPage.getNumber());
148	        ownerPageDto.setSize(ownerPage.getSize());
149	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
150	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
151	        return ownerPageDto;
152	    }
153	}
